    // Descending order
    sort(arr, arr + n, greater<int>());
    for(int i = 0; i < n; i++) cout << arr[i] << " ";  // 9 8 5 3 2 1

    // stable_sort preserves order of equal elements
    // stable_sort(arr, arr + n);
    return 0;
}

