        // Arrays.sort - uses Dual-Pivot QuickSort for primitives
        int[] arr = {5, 2, 8, 1, 9, 3};

        // Ascending order
        Arrays.sort(arr);
        System.out.println(Arrays.toString(arr));  // [1, 2, 3, 5, 8, 9]

